/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #141026;
  --color-panel: #272147;
  --color-panel-light: #362f5e;
  --color-accent: #fcd036;
  --color-accent-shadow: #b38f17;
  --color-text: #ffffff;
  --color-text-dim: #9e9ac2;
  --color-danger: #ff5277;
  --color-success: #5af59a;
  --pixel-border: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Courier New", Courier, monospace, system-ui, -apple-system, sans-serif;
  font-size: 16px;
  background-color: var(--color-bg);
  color: var(--color-text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1.5rem 1rem;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 20px 20px;
}

.converter-container {
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Header */
.pixel-header {
  text-align: center;
  background: var(--color-panel);
  padding: 1.25rem 1rem;
  border: var(--pixel-border) solid var(--color-text);
  box-shadow:
    inset -4px -4px 0px 0px rgba(0, 0, 0, 0.4),
    4px 4px 0px 0px #000000;
}

.pixel-icon {
  font-size: 2rem;
  margin-bottom: 0.25rem;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px #000000;
  margin-bottom: 0.35rem;
}

.subtitle {
  font-size: 0.875rem;
  color: var(--color-text-dim);
  letter-spacing: 1px;
}

/* Main Card */
.converter-card {
  background: var(--color-panel);
  padding: 1.5rem;
  border: var(--pixel-border) solid var(--color-text);
  box-shadow:
    inset -4px -4px 0px 0px rgba(0, 0, 0, 0.4),
    6px 6px 0px 0px #000000;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.conversion-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.group-label {
  font-size: 1rem;
  font-weight: bold;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.badge {
  background: var(--color-accent);
  color: #000000;
  padding: 0.15rem 0.4rem;
  font-size: 0.75rem;
  font-weight: 900;
  box-shadow: 2px 2px 0px 0px #000000;
}

.input-wrapper {
  display: flex;
  gap: 0.5rem;
}

input[type="number"],
input[type="text"] {
  flex: 1;
  min-width: 0;
  background-color: #0d0a1a;
  color: var(--color-text);
  border: 3px solid var(--color-text-dim);
  padding: 0.65rem 0.75rem;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  outline: none;
  box-shadow: inset 2px 2px 0px 0px rgba(0, 0, 0, 0.6);
}

input:focus {
  border-color: var(--color-accent);
  box-shadow:
    inset 2px 2px 0px 0px rgba(0, 0, 0, 0.6),
    0 0 0 2px var(--color-accent-shadow);
}

.input-help {
  font-size: 0.75rem;
  color: var(--color-text-dim);
}

/* Buttons */
.pixel-btn {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: bold;
  background-color: var(--color-panel-light);
  color: var(--color-text);
  border: 3px solid var(--color-text);
  padding: 0.4rem 0.75rem;
  cursor: pointer;
  box-shadow: 3px 3px 0px 0px #000000;
  transition: none;
  user-select: none;
}

.pixel-btn:hover {
  background-color: var(--color-accent);
  color: #000000;
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px 0px #000000;
}

.btn-small {
  padding: 0.65rem 0.75rem;
}

/* Results Display */
.result-box {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  background: #110d24;
  border: 2px dashed var(--color-text-dim);
  padding: 0.75rem 1rem;
  margin-top: 0.25rem;
}

.result-label {
  font-size: 0.875rem;
  color: var(--color-text-dim);
}

.result-value {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--color-accent);
  word-break: break-all;
}

.result-value.invalid {
  color: var(--color-danger);
}

.result-value.valid {
  color: var(--color-success);
}

/* Divider */
.divider {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin: 0.25rem 0;
  color: var(--color-accent);
}

.pixel-line {
  flex: 1;
  height: 2px;
  background: repeating-linear-gradient(
    90deg,
    var(--color-text-dim),
    var(--color-text-dim) 4px,
    transparent 4px,
    transparent 8px
  );
}

.pixel-gem {
  font-size: 0.75rem;
}

/* Presets */
.presets-section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.25rem;
}

.preset-title {
  font-size: 0.8rem;
  color: var(--color-text-dim);
}

.preset-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.preset-btn {
  font-size: 0.8rem;
  padding: 0.35rem 0.6rem;
  background: #1a1533;
  border-color: var(--color-text-dim);
}

/* Reference Card */
.reference-card {
  background: var(--color-panel);
  padding: 1rem;
  border: var(--pixel-border) solid var(--color-text-dim);
  box-shadow: 4px 4px 0px 0px #000000;
}

.reference-title {
  font-size: 0.85rem;
  letter-spacing: 1px;
  margin-bottom: 0.75rem;
  color: var(--color-accent);
  text-align: center;
}

.symbol-grid {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(60px, 1fr));
  gap: 0.5rem;
  text-align: center;
  font-size: 0.85rem;
}

.symbol-grid li {
  background: #181330;
  padding: 0.35rem 0.2rem;
  border: 1px solid var(--color-panel-light);
}

.sym {
  font-weight: bold;
  color: var(--color-accent);
}

/* Responsiveness */
@media (max-width: 420px) {
  body {
    padding: 0.75rem 0.5rem;
  }

  .converter-card {
    padding: 1rem;
  }

  .title {
    font-size: 1.25rem;
  }

  .result-box {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.25rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const numberInput = document.getElementById('number-input');
  const romanInput = document.getElementById('roman-input');
  const romanResultDisplay = document.getElementById('roman-result-display');
  const numberResultDisplay = document.getElementById('number-result-display');
  const clearNumberBtn = document.getElementById('clear-number-btn');
  const clearRomanBtn = document.getElementById('clear-roman-btn');
  const presetButtons = document.querySelectorAll('.preset-btn');

  // Lookup table for standard conversions
  const ROMAN_MAP = [
    { value: 1000, numeral: 'M' },
    { value: 900, numeral: 'CM' },
    { value: 500, numeral: 'D' },
    { value: 400, numeral: 'CD' },
    { value: 100, numeral: 'C' },
    { value: 90, numeral: 'XC' },
    { value: 50, numeral: 'L' },
    { value: 40, numeral: 'XL' },
    { value: 10, numeral: 'X' },
    { value: 9, numeral: 'IX' },
    { value: 5, numeral: 'V' },
    { value: 4, numeral: 'IV' },
    { value: 1, numeral: 'I' }
  ];

  // Strict regex for standard subtractive Roman numerals from 1 to 3999
  const STRICT_ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  /**
   * Converts an integer in range [1, 3999] to Roman numerals.
   * Returns null if out of range or not an integer.
   */
  function toRoman(num) {
    if (typeof num !== 'number' || isNaN(num) || !Number.isInteger(num)) {
      return null;
    }
    if (num < 1 || num > 3999) {
      return null;
    }

    let result = '';
    let remaining = num;
    for (const item of ROMAN_MAP) {
      while (remaining >= item.value) {
        result += item.numeral;
        remaining -= item.value;
      }
    }
    return result;
  }

  /**
   * Converts Roman numeral string to an integer in range [1, 3999].
   * Validates both canonical syntax and matching round-trip value.
   * Returns null if invalid.
   */
  function fromRoman(str) {
    if (typeof str !== 'string') return null;
    const clean = str.trim().toUpperCase();
    if (!clean) return null;
    if (!STRICT_ROMAN_REGEX.test(clean)) return null;

    let sum = 0;
    let i = 0;
    while (i < clean.length) {
      let matched = false;
      for (const item of ROMAN_MAP) {
        if (clean.startsWith(item.numeral, i)) {
          sum += item.value;
          i += item.numeral.length;
          matched = true;
          break;
        }
      }
      if (!matched) return null;
    }

    if (sum < 1 || sum > 3999) return null;
    // Verify canonical representation round-trip (rejects malformed like IIII, VV, IC, etc.)
    if (toRoman(sum) !== clean) return null;

    return sum;
  }

  // UI update helper for Number input
  function handleNumberInput() {
    const val = numberInput.value.trim();
    if (val === '') {
      romanResultDisplay.textContent = '-';
      romanResultDisplay.className = 'result-value';
      return;
    }

    const parsed = Number(val);
    const roman = toRoman(parsed);

    if (roman) {
      romanResultDisplay.textContent = roman;
      romanResultDisplay.className = 'result-value valid';
    } else {
      romanResultDisplay.textContent = 'Not valid';
      romanResultDisplay.className = 'result-value invalid';
    }
  }

  // UI update helper for Roman input
  function handleRomanInput() {
    const raw = romanInput.value.trim();
    if (raw === '') {
      numberResultDisplay.textContent = '-';
      numberResultDisplay.className = 'result-value';
      return;
    }

    const num = fromRoman(raw);
    if (num !== null) {
      numberResultDisplay.textContent = num.toString();
      numberResultDisplay.className = 'result-value valid';
    } else {
      numberResultDisplay.textContent = 'Not valid';
      numberResultDisplay.className = 'result-value invalid';
    }
  }

  // Event Listeners
  numberInput.addEventListener('input', handleNumberInput);
  romanInput.addEventListener('input', handleRomanInput);

  clearNumberBtn.addEventListener('click', () => {
    numberInput.value = '';
    handleNumberInput();
    numberInput.focus();
  });

  clearRomanBtn.addEventListener('click', () => {
    romanInput.value = '';
    handleRomanInput();
    romanInput.focus();
  });

  // Preset buttons
  presetButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const val = btn.getAttribute('data-val');
      if (val) {
        numberInput.value = val;
        handleNumberInput();

        const romanConverted = toRoman(Number(val));
        if (romanConverted) {
          romanInput.value = romanConverted;
          handleRomanInput();
        }
      }
    });
  });
});
